from functools import lru_cache


@lru_cache(maxsize=None)
def _beautiful_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count valid completions after a nonzero first digit."""
    if remaining == 0:
        return int(product % digit_sum == 0)
    # Choosing zero makes the product zero, so every subsequent suffix works.
    total = 10 ** (remaining - 1)
    for digit in range(1, 10):
        total += _beautiful_suffix(remaining - 1, digit_sum + digit, product * digit)
    return total


@lru_cache(maxsize=None)
def _beautiful_upto(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(digit) for digit in str(bound)]
    size = len(digits)
    total = 0
    # Count shorter positive numbers, with no leading zero.
    for length in range(1, size):
        for first in range(1, 10):
            total += _beautiful_suffix(length - 1, first, first)

    digit_sum = 0
    product = 1
    for index, limit in enumerate(digits):
        remaining = size - index - 1
        for digit in range(1 if index == 0 else 0, limit):
            if product == 0 or digit == 0:
                total += 10 ** remaining
            else:
                total += _beautiful_suffix(remaining, digit_sum + digit, product * digit)
        digit_sum += limit
        product *= limit
    total += int(product % digit_sum == 0)
    return total


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product divides evenly
    by their digit sum.

    Constraints: 1 <= l <= r < 10**9.
    """
    return _beautiful_upto(r) - _beautiful_upto(l - 1)

from typing import List
from math import gcd


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """ Given an array of coin denominations and an integer k, return the k-th smallest amount
    that can be made using these coins. You have infinite coins of each denomination, but
    cannot combine coins of different denominations in a single amount.

    Each coin denomination produces its multiples (e.g., coin 3 produces 3, 6, 9, 12, ...).
    The k-th smallest among all possible amounts from all denominations is returned.

    Args:
        coins: List of distinct positive integers representing coin denominations (1-15 elements, each 1-25)
        k: The position of the desired amount (1-based indexing, 1 <= k <= 2*10^9)

    Returns:
        The k-th smallest amount that can be made

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # A denomination divisible by a smaller one adds no new amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    low, high = 1, denominations[0] * k
    # Combine inclusion-exclusion terms with the same least common multiple.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for divisor, coefficient in coefficients.items():
            common = divisor // gcd(divisor, coin) * coin
            if common <= high:
                changes[common] = changes.get(common, 0) - coefficient
        for divisor, coefficient in changes.items():
            total = coefficients.get(divisor, 0) + coefficient
            if total:
                coefficients[divisor] = total
            else:
                coefficients.pop(divisor, None)

    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // divisor)
                    for divisor, coefficient in coefficients.items())
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

from math import isqrt


def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    # For x > 1, let g be the gcd of its prime factorization exponents.
    # The indicator that g > 1 is -sum(mu(k) for k | g, k >= 2).
    # Counting kth powers and applying this identity counts each x once.
    limit = n.bit_length() - 1
    mu = [1] * (limit + 1)
    prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if prime[p]:
            for multiple in range(p, limit + 1, p):
                prime[multiple] = False
                mu[multiple] = -mu[multiple]
            for multiple in range(p * p, limit + 1, p * p):
                mu[multiple] = 0

    def integer_root(k: int) -> int:
        if k == 2:
            return isqrt(n)
        low, high = 1, 1 << ((n.bit_length() + k - 1) // k)
        while low + 1 < high:
            middle = (low + high) // 2
            if middle ** k <= n:
                low = middle
            else:
                high = middle
        return low

    # 1 is a perfect power, but is excluded from every root count below.
    answer = 1
    for k in range(2, limit + 1):
        if mu[k]:
            answer -= mu[k] * (integer_root(k) - 1)
    return answer
